-- search_customers after #17: cxp_core::customers::SEARCH_CUSTOMERS_SQL with
-- pgbench variables for its binds (regenerate if that SQL changes).
BEGIN;
SET LOCAL ROLE otto_app;
SELECT set_config('app.org_id', :org, true);
SET LOCAL jit = off;
WITH w AS ( SELECT DISTINCT 's' || g AS gram FROM search_windows(lower(:q)) AS g ), ranked AS ( SELECT gram, row_number() OVER (ORDER BY n, gram) AS rk FROM ( SELECT w.gram, (SELECT count(*) FROM (SELECT 1 FROM customer_search_grams g WHERE g.org_id = :org::uuid AND g.gram = w.gram LIMIT 256) AS p) AS n FROM w) AS c ), substring_hits AS ( SELECT g.customer_id FROM customer_search_grams g WHERE g.org_id = :org::uuid AND g.gram = (SELECT gram FROM ranked WHERE rk = 1) AND NOT EXISTS (SELECT 1 FROM ranked r WHERE r.rk IN (2, 3) AND NOT EXISTS ( SELECT 1 FROM customer_search_grams g2 WHERE g2.org_id = :org::uuid AND g2.gram = r.gram AND g2.customer_id = g.customer_id)) UNION SELECT g.customer_id FROM customer_search_grams g WHERE length(lower(:q)) < 4 AND g.org_id = :org::uuid AND g.gram >= 's' || lower(:q) AND g.gram <= 's' || lower(:q) || U&'\+10FFFF\+10FFFF\+10FFFF' ), fq AS ( SELECT 't' || t AS gram, (SELECT count(*) FROM (SELECT 1 FROM customer_search_grams g WHERE g.org_id = :org::uuid AND g.gram = 't' || t LIMIT 256) AS p) AS n, CASE WHEN t LIKE ' %' THEN 2 WHEN t LIKE ' %' THEN 1 ELSE 0 END AS shape FROM unnest(show_trgm(:q)) AS t ), fz AS ( SELECT gram, row_number() OVER (ORDER BY n, shape, gram) AS rk FROM fq ), fp AS ( SELECT b, th, greatest(ceil(th * b - 0.001), 1) AS kmin FROM ( SELECT (SELECT count(*) FROM fq) AS b, current_setting('pg_trgm.similarity_threshold')::float8 AS th) AS x ), fuzzy_hits AS ( SELECT g.customer_id FROM customer_search_grams g WHERE g.org_id = :org::uuid AND g.gram = ANY (ARRAY(SELECT gram FROM fz, fp WHERE fz.rk <= fp.b - fp.kmin + 1)) GROUP BY g.customer_id HAVING count(*) >= ceil((SELECT th FROM fp) * (max(g.name_grams) + (SELECT b FROM fp)) / (1 + (SELECT th FROM fp)) - 0.001) - ((SELECT kmin FROM fp) - 1) UNION ALL SELECT id FROM customers WHERE org_id = :org::uuid AND current_setting('pg_trgm.similarity_threshold')::float8 <= 0 ) SELECT id, email, name, phone, company, metadata, tags, experience_id, application_id, page_id, component_id, created_at, updated_at FROM customers WHERE org_id = :org::uuid AND id = ANY (ARRAY(SELECT customer_id FROM substring_hits UNION SELECT customer_id FROM fuzzy_hits)) AND (email ILIKE :pat OR name ILIKE :pat OR name % :q) ORDER BY CASE WHEN email ILIKE :pat THEN 0 ELSE 1 END, similarity(name, :q) DESC NULLS LAST, created_at DESC, id LIMIT 50 OFFSET 0;
COMMIT;
